// THE WORLD TODAY — a one-page newspaper summing up Friday 27 November 2026.
// The front page is drawn with Python/PIL (flat shapes, DejaVu type) and embedded
// below as base64, so this program needs no network and no fonts at run time.
// It validates the image before writing it: PNG signature, 1024x1024 dimensions,
// IEND trailer, and the exact sha256 of the bytes it ships.
//
// The five stories on the page, all reported on Friday 27 November 2026:
//   1. USA — a storm wrecks Thanksgiving: 900,000 lose power, Macy's parade
//      postponed for weather for the first time in 100 years.
//   2. MIDDLE EAST — Israeli drone strike kills 3 in Gaza City; seven killed
//      in the Strip, including a deputy minister.
//   3. EUROPE — US approves a $622m F-16 support package for Ukraine, paid
//      for by European allies.
//   4. AFRICA — a fuel tanker fire in Giza, Egypt, kills at least 31.
//   5. DIPLOMACY — Trump says he pressed Putin in China to end aggression
//      in Europe; talks Ukraine and Iran with NATO chief Rutte.
// Also today: Kim Jong Un halts military aid to Russia (Kyiv intelligence);
// Hong Kong marks one year since its deadly high-rise fire.
//
// Run locally:  mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts
// The grader runs it twice; both runs must write byte-identical output, which
// holds here because the bytes come from a fixed embedded constant.

import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

// sha256 of entry.png, the image this program writes.
const EXPECTED_SHA256 = '88bc97c4c2fcf05e44aff93e687fb829b529e1ffbf03793a900996f34ac7ac5f';

// The whole entry.png, base64-encoded, on one line (the image itself).
const PNG_BASE64 = '';

const bytes = Buffer.from(PNG_BASE64, 'base64');

// A PNG starts with its 8-byte signature, then the IHDR chunk.
const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
if (bytes.length < 33 || !bytes.subarray(0, 8).equals(PNG_SIGNATURE)) {
  throw new Error('embedded data is not a PNG');
}
if (bytes.toString('ascii', 12, 16) !== 'IHDR') {
  throw new Error('embedded PNG has no IHDR chunk');
}
const width = bytes.readUInt32BE(16);
const height = bytes.readUInt32BE(20);
if (width !== 1024 || height !== 1024) {
  throw new Error(`expected a 1024x1024 image, got ${width}x${height}`);
}
// A whole PNG ends with the 12-byte IEND chunk (length 0, "IEND", fixed CRC).
const IEND = Buffer.from([0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82]);
if (bytes.length < 12 || !bytes.subarray(bytes.length - 12).equals(IEND)) {
  throw new Error('embedded PNG is truncated: no IEND chunk at the end');
}
if (bytes.length > 1048576) {
  throw new Error(`image is ${bytes.length} bytes, over the 1 MiB limit`);
}
const actualSha256 = createHash('sha256').update(bytes).digest('hex');
if (actualSha256 !== EXPECTED_SHA256) {
  throw new Error('embedded image failed its sha256 check');
}

const outDir = process.env.MAKEFUN_OUTPUT_DIR?.trim() ? process.env.MAKEFUN_OUTPUT_DIR : '/output';
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'entry.png'), bytes);
